/* From Uiverse.io by nanda248 - Tags: card, playing card, uno */
.__UIV_SCOPE__ .card {
  width: 11em;
  height: 14.8em;
  position: relative;
  background: #28282B;
  display: flex;
  justify-content: center;
  align-items: center;
  border: 6px solid #F5F5DC;
  border-radius: 5px;
  transition: 0.5s;
  overflow: hidden;
}

.__UIV_SCOPE__ .card .circle {
  width: 8em;
  height: 14em;
  border-radius: 50%;
  transform: skew(-25deg);
  border: 4px solid white;
  display: grid;
  grid-template-columns: 1fr 1fr;
}

.__UIV_SCOPE__ .card .circle.small {
  position: absolute;
  width: 1.5em;
  height: 3em;
  border: 1px solid white;
}

.__UIV_SCOPE__ .card .circle.top-left {
  top: 0.3em;
  left: 0.6em;
}

.__UIV_SCOPE__ .card .circle.bottom-right {
  bottom: 0.3em;
  right: 0.6em;
}

.__UIV_SCOPE__ .card:hover {
  cursor: pointer;
  transform: translate(0, -5px);
}

.__UIV_SCOPE__ .card:hover:after, .__UIV_SCOPE__ .card:hover:before {
  visibility: hidden;
}

.__UIV_SCOPE__ .card .circle span:nth-child(1) {
  background-color: #FF2400;
  border-top-left-radius: 100%;
}

.__UIV_SCOPE__ .card .circle span:nth-child(2) {
  background-color: #1F51FF;
  border-top-right-radius: 100%;
}

.__UIV_SCOPE__ .card .circle span:nth-child(3) {
  background-color: #FFEA00;
  border-bottom-left-radius: 100%;
}

.__UIV_SCOPE__ .card .circle span:nth-child(4) {
  background-color: #50C878;
  border-bottom-right-radius: 100%;
}

/* glider animation */
.__UIV_SCOPE__ .card:before {
  content: '';
  position: absolute;
  height: 130%;
  width: 1em;
  background-color: aliceblue;
  opacity: 0.14;
  animation: glider 1.8s infinite linear;
  animation-delay: 0.05s;
}

.__UIV_SCOPE__ .card:after {
  content: '';
  position: absolute;
  height: 120%;
  width: 0.8em;
  background-color: aliceblue;
  opacity: 0.1;
  animation: glider 1.8s infinite linear;
}

@keyframes glider {
  0% {
    transform: rotate(45deg) translate(-12em, 1.2em);
  }

  100% {
    transform: rotate(45deg) translate(18em, -2.8em);
  }
}
